//
// protocol_v5.h — PROTOCOL v5 (MONITOR: device app, 4 values, alerts from the
// edges), ESP32 side.
//
// Exact mirror of `source-monitor/ProtocolV5.mc`: the offset tables are
// reproduced IDENTICALLY in both files. C bitfields are FORBIDDEN. The full
// specification is docs/v5_monitoring.md, the single source of truth for V5;
// the vectors of the C test are generated by tools/check_v5.py.
//
// ===========================================================================
// RELATION TO THE OTHER PROTOCOLS
// ===========================================================================
// Transport: the v3 one, unchanged (flags = PROTO_FMT_APP). Same magic as v4:
// proto_ver = 0x06 tells them apart. All big-endian, like v4. The CRCs are
// those of protocol_v3.h (v3_crc16, v3_crc8).
//
// The uplink parser and the per-node continuity are in monitor.c, on the same
// model as multi.c for v4; this file keeps the format, the alert and the
// routing (v5_route_monitor).
//
// ===========================================================================
// UPLINK — FR255 -> ESP32
// ===========================================================================
//
// HEADER — 16 bytes (the first 14 are those of v4)
//
//   | Off | Type   | Field      | Notes                                         |
//   |-----|--------|------------|-----------------------------------------------|
//   |  0  | uint8  | magic      | 0xA5                                          |
//   |  1  | uint8  | proto_ver  | 0x06                                          |
//   |  2  | uint8  | node_id    | DESTINATION edge                              |
//   |  3  | uint8  | n_samples  | 0..8; 0 = alert confirmations only            |
//   |  4  | uint32 | session_id | epoch of the app opening (the session)        |
//   |  8  | uint32 | seq_first  | seq of the 1st sample (with n = 0: the next)  |
//   | 12  | uint8  | backlog    | samples queued AFTER these (saturates at 255) |
//   | 13  | uint8  | conn_no    | connection number in the session (mod 256)    |
//   | 14  | uint8  | ev_ack     | last alert RECEIVED from this edge            |
//   | 15  | uint8  | ev_user    | last alert CONFIRMED by the user              |
//
//   ev_ack and ev_user are cumulative (7 also confirms 6); 0 = none.
//
// SAMPLE — 12 bytes
//
//   | Off | Type   | Field    | Encoding                                       |
//   |-----|--------|----------|------------------------------------------------|
//   |  0  | uint32 | realTime | UTC epoch (s)                                  |
//   |  4  | uint16 | hr       | bpm                                            |
//   |  6  | uint16 | batt     | % x 100 (0..10000)                             |
//   |  8  | uint16 | steps    | steps of the day                               |
//   | 10  | uint16 | alt      | metres + 10000                                 |
//
//   Missing value: 0xFFFF.
//
// TRAILER — 2 bytes: BE uint16 crc16 over EVERYTHING else.
//
// SIZES: 18 + 12*n.  n=0 -> 18 B (2 chunks), n=1 -> 30 B (2 chunks),
//                    n=4 -> 66 B (5 chunks), n=8 -> 114 B (8 chunks).
//
// ===========================================================================
// ALERT — ESP32 -> FR255, one 20-byte notification on the ALERT
// characteristic (51FF12BB-3ED8-46E5-B4F9-D64E25E01DBB)
// ===========================================================================
//
//   | Off | Type     | Field     | Notes                                      |
//   |-----|----------|-----------|--------------------------------------------|
//   |  0  | uint8    | magic     | 0x5A                                       |
//   |  1  | uint8    | proto_ver | 0x06                                       |
//   |  2  | uint8    | node_id   | sending edge                               |
//   |  3  | uint8    | ev_seq    | 1..255 per edge; 0 is not used             |
//   |  4  | uint8    | ev_type   | 0 test, 1 info, 2 warning, 3 danger        |
//   |  5  | uint8    | alert     | bit0 vibration, bit1 sound; 0 = message    |
//   |  6  | uint16   | ev_value  | parameter; 0xFFFF = none                   |
//   |  8  | char[11] | text      | ASCII, zero-padded; empty = type text      |
//   | 19  | uint8    | crc8      | over bytes 0..18                           |
//
// 20 bytes is the maximum for a notification with the default MTU (23):
// Connect IQ does not negotiate the MTU.
//
#pragma once
#include <stdint.h>
#include <stdbool.h>

#include "protocol_v3.h"   // v3_crc16, v3_crc8

// --- Identification ---
#define V5_MAGIC_UP        0xA5u   // = V4_MAGIC: proto_ver decides
#define V5_MAGIC_DOWN      0x5Au   // magic of the alert
#define V5_VER             0x06u

// --- Uplink geometry ---
#define V5_HDR_BYTES       16
#define V5_SAMPLE_BYTES    12
#define V5_CRC_BYTES       2
#define V5_MAX_SAMPLES     8
#define V5_MAX_PKT_BYTES   (V5_HDR_BYTES + V5_MAX_SAMPLES * V5_SAMPLE_BYTES + V5_CRC_BYTES)  // 114

// --- Header offsets ---
#define V5_H_MAGIC         0
#define V5_H_VER           1
#define V5_H_NODE          2
#define V5_H_NSAMPLES      3
#define V5_H_SESSION       4
#define V5_H_SEQ           8
#define V5_H_BACKLOG       12
#define V5_H_CONNNO        13
#define V5_H_EV_ACK        14
#define V5_H_EV_USER       15

// --- Sample offsets ---
#define V5_S_TIME          0
#define V5_S_HR            4
#define V5_S_BATT          6
#define V5_S_STEPS         8
#define V5_S_ALT           10

// --- Values ---
#define V5_ABSENT          0xFFFFu   // "value missing"
#define V5_ALT_OFFSET      10000     // altitude: metres + 10000, as in v3

// --- Alert ---
#define V5_ALERT_BYTES     20
#define V5_TEXT_BYTES      11
#define V5_A_MAGIC         0
#define V5_A_VER           1
#define V5_A_NODE          2
#define V5_A_SEQ           3
#define V5_A_TYPE          4
#define V5_A_ALERT         5
#define V5_A_VALUE         6
#define V5_A_TEXT          8
#define V5_A_CRC8          19

#define V5_AL_VIBE         0x01u     // bits of the alert field
#define V5_AL_TONE         0x02u

#define V5_EV_TEST         0         // ev_type
#define V5_EV_INFO         1
#define V5_EV_WARN         2
#define V5_EV_DANGER       3

#define V5_VALUE_NONE      0xFFFFu

// Routing of the APP payload (flags = 0b11): true if proto_ver (offset 1, the
// same in v4 and v5, with the same magic) is the v5 one. Everything else goes
// to the v4 parser, which accepts only 0x05: any other version gets an ATT
// error and stays in the watch queue, instead of being confirmed and lost.
static inline bool v5_route_monitor(const uint8_t *buf, uint32_t len) {
    return len > V5_H_VER && buf[V5_H_VER] == V5_VER;
}

static inline uint16_t v5_be16(const uint8_t *p) {
    return (uint16_t)(((uint16_t)p[0] << 8) | (uint16_t)p[1]);
}

// Expected size of a v5 packet with n samples (n = 0: confirmations only).
static inline uint32_t v5_expected_len(uint8_t n_samples) {
    return (uint32_t)V5_HDR_BYTES + (uint32_t)n_samples * V5_SAMPLE_BYTES + V5_CRC_BYTES;
}

// Next ev_seq: 1..255, then 1 again. 0 is not used (the watch discards an
// alert with ev_seq = 0, and in the uplink 0 means "none").
static inline uint8_t v5_next_ev_seq(uint8_t seq) {
    return (seq >= 255u) ? 1u : (uint8_t)(seq + 1u);
}

// 20-byte alert, ready for the notification. Of the alert field only vibration
// and sound are kept (bits 2-7 are reserved and set to 0). The text is copied
// up to the first '\0' or 11 bytes, and the rest is filled with 0; text = NULL
// is the same as an empty text (the watch shows the ev_type text).
static inline void v5_build_alert(uint8_t node_id, uint8_t ev_seq, uint8_t ev_type,
                                  uint8_t alert, uint16_t ev_value, const char *text,
                                  uint8_t out[V5_ALERT_BYTES]) {
    out[V5_A_MAGIC]     = V5_MAGIC_DOWN;
    out[V5_A_VER]       = V5_VER;
    out[V5_A_NODE]      = node_id;
    out[V5_A_SEQ]       = ev_seq;
    out[V5_A_TYPE]      = ev_type;
    out[V5_A_ALERT]     = (uint8_t)(alert & (V5_AL_VIBE | V5_AL_TONE));
    out[V5_A_VALUE]     = (uint8_t)(ev_value >> 8);
    out[V5_A_VALUE + 1] = (uint8_t)(ev_value & 0xFFu);
    int i = 0;
    for (; text != NULL && i < V5_TEXT_BYTES && text[i] != '\0'; i++) {
        out[V5_A_TEXT + i] = (uint8_t)text[i];
    }
    for (; i < V5_TEXT_BYTES; i++) {
        out[V5_A_TEXT + i] = 0;
    }
    out[V5_A_CRC8] = v3_crc8(out, V5_A_CRC8);
}
